const state = { stage: 'reference', rightTab: 'reference', currentTask: 'joint', selectedIssue: 'joint', confirmed: false, history: [] };
const $ = (id) => document.getElementById(id);
const toast = (message) => { const el = $('toast'); el.textContent = message; el.classList.remove('hidden'); el.classList.add('show'); setTimeout(() => el.classList.add('hidden'), 2200); };
const renderRightTab = (tab) => { document.querySelectorAll('.right-tab').forEach((button) => button.classList.toggle('active', button.dataset.rightTab === tab)); document.querySelectorAll('.right-context').forEach((panel) => panel.classList.toggle('hidden', panel.dataset.rightContent !== tab)); };
const setRightTab = (tab) => { state.rightTab = tab; history.pushState({ tab }, '', `#${tab}`); renderRightTab(tab); };
const renderStage = () => { $('reference-state').classList.toggle('hidden', state.stage !== 'reference'); $('model-state').classList.toggle('hidden', state.stage !== 'model'); $('airport-state').classList.toggle('hidden', state.stage !== 'airport'); $('stage-eyebrow').textContent = state.stage === 'reference' ? '参考已导入 · 结构候选未确认' : state.stage === 'model' ? (state.confirmed ? '设计已确认 · 可生成加工包' : '结构候选 · v3 draft') : 'Airport 预览 · v3'; $('stage-title').textContent = state.stage === 'reference' ? '先把喜欢的椅子看懂' : state.stage === 'model' ? '围绕模型继续设计' : '模型已进入 Airport'; $('commit-button').classList.toggle('locked', !state.confirmed || state.stage === 'airport'); $('commit-button').textContent = state.stage === 'airport' ? '已提交' : '生成三维预览'; $('save-state').textContent = state.confirmed ? '已保存 · v4' : '已保存 · v3'; if ($('canvas-focus')) $('canvas-focus').textContent = `当前聚焦：${({ joint:'座面与左侧板接合', load:'座面承载', dimensions:'整体尺寸', validation:'待检查问题', fabrication:'全体部件' })[state.currentTask] || '整体模型'}`; if (typeof renderWebgl === 'function') renderWebgl(); };
const renderTasks = () => { document.querySelectorAll('.task-card').forEach((el) => { const active = el.dataset.task === state.currentTask; el.classList.toggle('current', active); el.classList.toggle('expanded', active); }); };
const render = () => { renderStage(); renderTasks(); renderRightTab(state.rightTab); };
document.querySelectorAll('.right-tab').forEach((button) => button.addEventListener('click', () => setRightTab(button.dataset.rightTab)));
document.querySelectorAll('[data-panel]').forEach((el) => el.addEventListener('click', () => setRightTab(el.dataset.panel === 'design' ? 'layers' : el.dataset.panel)));
document.querySelectorAll('.task-card[data-task]').forEach((el) => el.addEventListener('click', (event) => { if (event.target.closest('button')) return; state.currentTask = el.dataset.task; state.selectedIssue = el.dataset.task; if (el.dataset.task !== 'reference') state.stage = 'model'; render(); toast(el.querySelector('strong').textContent); }));
document.querySelectorAll('[data-action="generate"]').forEach((el) => el.addEventListener('click', () => { state.stage = 'model'; render(); toast('已生成结构候选，等待确认'); }));
document.querySelectorAll('[data-action="confirm"]').forEach((el) => el.addEventListener('click', () => { state.confirmed = true; render(); toast('设计已确认，加工包已解锁'); }));
document.querySelectorAll('[data-action="apply-joint"]').forEach((el) => el.addEventListener('click', () => { const task = document.querySelector('[data-task="joint"]'); task.querySelector('.task-summary strong').textContent = '接合方式已确认'; task.querySelector('.task-summary small').textContent = '已完成 · 半搭接'; state.currentTask = 'load'; state.selectedIssue = 'load'; state.stage = 'model'; render(); toast('已应用半搭接，已跳到下一项：预计承重'); }));
document.querySelectorAll('[data-action="answer-load"]').forEach((el) => el.addEventListener('click', () => { const task = document.querySelector('[data-task="load"]'); task.querySelector('.task-summary strong').textContent = '预计承重已填写'; task.querySelector('.task-summary small').textContent = '已完成 · 80 kg'; state.currentTask = 'dimensions'; state.selectedIssue = 'dimensions'; render(); toast('已填写 80 kg，已跳到下一项：尺寸与材料'); }));
document.querySelectorAll('[data-action="ask-load"]').forEach((el) => el.addEventListener('click', () => toast('AI 会先解释承载估算需要哪些信息')));
document.querySelectorAll('[data-action="open-dimensions"]').forEach((el) => el.addEventListener('click', () => { setRightTab('layers'); toast('右侧已打开图层，画布聚焦整体尺寸'); }));
document.querySelectorAll('[data-action="select-joint"]').forEach((el) => el.addEventListener('click', () => toast('原型中保留接合候选选择位置')));
document.querySelectorAll('[data-action="commit"]').forEach((el) => el.addEventListener('click', () => { if (!state.confirmed) { toast('请先确认设计'); return; } state.stage = 'airport'; render(); toast('已生成三维预览'); }));
document.querySelectorAll('[data-action="back-model"]').forEach((el) => el.addEventListener('click', () => { state.stage = 'model'; render(); }));
document.querySelectorAll('[data-action="close-panel"]').forEach((el) => el.addEventListener('click', () => { document.querySelector('.right-panel').classList.toggle('closed'); }));
document.querySelectorAll('[data-action="export"], [data-action="focus-package"]').forEach((el) => el.addEventListener('click', () => { setRightTab('lists'); toast(state.confirmed ? '加工包已准备好下载' : '确认设计后才能导出加工包'); }));
document.querySelectorAll('[data-action="focus-reference"]').forEach((el) => el.addEventListener('click', () => setRightTab('reference')));
document.querySelectorAll('[data-action="focus-joint"]').forEach((el) => el.addEventListener('click', () => { state.selectedIssue = 'joint'; renderTasks(); toast('已定位到当前任务'); }));
document.querySelectorAll('.viewport-tool').forEach((el) => el.addEventListener('click', () => { document.querySelectorAll('.viewport-tool').forEach((tool) => tool.classList.remove('active')); el.classList.add('active'); const messages = { select:'选择部件', measure:'卷尺：点击两个点测量', move:'Gizmo：移动', rotate:'Gizmo：旋转', scale:'Gizmo：缩放', mirror:'Gizmo：镜像' }; toast(messages[el.dataset.tool] || `视口工具：${el.textContent}`); }));
document.querySelectorAll('[data-view]').forEach((el) => el.addEventListener('click', () => toast(`切换视图：${el.textContent}`)));
const canvas = $('canvas');
canvas.addEventListener('contextmenu', (event) => event.preventDefault());
canvas.addEventListener('mousedown', (event) => { if (event.button === 1) toast('中键拖动：旋转视角'); if (event.button === 2) toast('右键拖动：平移视角'); });
canvas.addEventListener('wheel', () => toast('滚轮：缩放视角'), { passive:true });
document.querySelectorAll('[data-command]').forEach((el) => el.addEventListener('click', () => { $('command-input').value = el.dataset.command; $('command-input').focus(); }));
$('command-input').addEventListener('keydown', (event) => { if (event.key === 'Enter') document.querySelector('[data-action="command"]').click(); });
document.querySelector('[data-action="command"]').addEventListener('click', () => { const value = $('command-input').value.trim(); if (!value) return; state.history.push(value); $('command-input').value = ''; toast(`AI 已收到：“${value}”`); state.selectedIssue = 'joint'; renderTasks(); });
window.addEventListener('popstate', (event) => { state.rightTab = event.state?.tab || 'reference'; render(); });

const viewportCanvas = $('viewport-canvas');
const juniorViewport = { mode:'select', theta:0.7, phi:1.0, distance:1.55, panX:0, panY:0, selected:0, drag:null, measurePoints:[] };
const viewportParts = [
  { name:'座面', size:[0.72,0.05,0.76], position:[0,0.42,0], rotation:0, scale:[1,1,1], color:[0.64,0.43,0.25] },
  { name:'左侧板', size:[0.10,0.395,0.76], position:[-0.41,0.21,0], rotation:0, scale:[1,1,1], color:[0.54,0.35,0.21] },
  { name:'右侧板', size:[0.10,0.395,0.76], position:[0.41,0.21,0], rotation:0, scale:[1,1,1], color:[0.54,0.35,0.21] },
];
const v3 = (a,b) => [a[0]-b[0],a[1]-b[1],a[2]-b[2]];
const dot3 = (a,b) => a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const cross3 = (a,b) => [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const norm3 = (a) => { const n=Math.hypot(...a)||1; return a.map((x)=>x/n); };
const matMul = (a,b) => { const o=new Float32Array(16); for(let c=0;c<4;c++) for(let r=0;r<4;r++) { let s=0; for(let k=0;k<4;k++) s+=a[k*4+r]*b[c*4+k]; o[c*4+r]=s; } return o; };
const matPerspective = (fovy,aspect,near,far) => { const f=1/Math.tan(fovy/2), o=new Float32Array(16); o[0]=f/aspect; o[5]=f; o[10]=(far+near)/(near-far); o[11]=-1; o[14]=(2*far*near)/(near-far); return o; };
const matLookAt = (eye,target,up) => { const z=norm3(v3(eye,target)), x=norm3(cross3(up,z)), y=cross3(z,x), o=new Float32Array(16); o[0]=x[0];o[1]=y[0];o[2]=z[0];o[4]=x[1];o[5]=y[1];o[6]=z[1];o[8]=x[2];o[9]=y[2];o[10]=z[2];o[12]=-dot3(x,eye);o[13]=-dot3(y,eye);o[14]=-dot3(z,eye);o[15]=1; return o; };
const partMatrix = (part) => { const c=Math.cos(part.rotation), s=Math.sin(part.rotation), sx=part.size[0]*part.scale[0], sy=part.size[1]*part.scale[1], sz=part.size[2]*part.scale[2], o=new Float32Array(16); o[0]=c*sx;o[2]=-s*sx;o[5]=sy;o[8]=s*sz;o[10]=c*sz;o[12]=part.position[0];o[13]=part.position[1];o[14]=part.position[2];o[15]=1; return o; };
const cubeVertices = new Float32Array([
  -0.5,-0.5,0.5, 0.5,-0.5,0.5, 0.5,0.5,0.5, -0.5,-0.5,0.5, 0.5,0.5,0.5, -0.5,0.5,0.5,
  -0.5,-0.5,-0.5, -0.5,0.5,-0.5, 0.5,0.5,-0.5, -0.5,-0.5,-0.5, 0.5,0.5,-0.5, 0.5,-0.5,-0.5,
  -0.5,0.5,-0.5, -0.5,0.5,0.5, 0.5,0.5,0.5, -0.5,0.5,-0.5, 0.5,0.5,0.5, 0.5,0.5,-0.5,
  -0.5,-0.5,-0.5, 0.5,-0.5,-0.5, 0.5,-0.5,0.5, -0.5,-0.5,-0.5, 0.5,-0.5,0.5, -0.5,-0.5,0.5,
  0.5,-0.5,-0.5, 0.5,0.5,-0.5, 0.5,0.5,0.5, 0.5,-0.5,-0.5, 0.5,0.5,0.5, 0.5,-0.5,0.5,
  -0.5,-0.5,-0.5, -0.5,-0.5,0.5, -0.5,0.5,0.5, -0.5,-0.5,-0.5, -0.5,0.5,0.5, -0.5,0.5,-0.5,
]);
let glState = null;
const createShader = (gl,type,source) => { const shader=gl.createShader(type); gl.shaderSource(shader,source); gl.compileShader(shader); return shader; };
const initWebgl = () => { if (!viewportCanvas) return; const gl=viewportCanvas.getContext('webgl'); if (!gl) { toast('当前浏览器不支持 WebGL，保留视口占位'); return; } const program=gl.createProgram(); gl.attachShader(program,createShader(gl,gl.VERTEX_SHADER,'attribute vec3 a_position; uniform mat4 u_matrix; void main(){gl_Position=u_matrix*vec4(a_position,1.0);}')); gl.attachShader(program,createShader(gl,gl.FRAGMENT_SHADER,'precision mediump float; uniform vec3 u_color; void main(){gl_FragColor=vec4(u_color,1.0);}')); gl.linkProgram(program); const buffer=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,buffer); gl.bufferData(gl.ARRAY_BUFFER,cubeVertices,gl.STATIC_DRAW); glState={gl,program,buffer,position:gl.getAttribLocation(program,'a_position'),matrix:gl.getUniformLocation(program,'u_matrix'),color:gl.getUniformLocation(program,'u_color')}; };
const renderWebgl = () => { if (!glState || !viewportCanvas || state.stage !== 'model') return; const {gl,program,buffer,position,matrix,color}=glState; const dpr=window.devicePixelRatio||1, w=Math.max(1,Math.floor(viewportCanvas.clientWidth*dpr)), h=Math.max(1,Math.floor(viewportCanvas.clientHeight*dpr)); if(viewportCanvas.width!==w||viewportCanvas.height!==h){viewportCanvas.width=w;viewportCanvas.height=h;} gl.viewport(0,0,w,h); gl.enable(gl.DEPTH_TEST); gl.clearColor(0.91,0.91,0.88,1); gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT); const eye=[juniorViewport.panX+juniorViewport.distance*Math.sin(juniorViewport.phi)*Math.sin(juniorViewport.theta),juniorViewport.panY+juniorViewport.distance*Math.cos(juniorViewport.phi),juniorViewport.distance*Math.sin(juniorViewport.phi)*Math.cos(juniorViewport.theta)], view=matLookAt(eye,[juniorViewport.panX,juniorViewport.panY+0.2,0],[0,1,0]), proj=matPerspective(0.8,w/h,0.01,20); gl.useProgram(program); gl.bindBuffer(gl.ARRAY_BUFFER,buffer); gl.enableVertexAttribArray(position); gl.vertexAttribPointer(position,3,gl.FLOAT,false,0,0); viewportParts.forEach((part,index)=>{ const model=partMatrix(part), m=matMul(matMul(proj,view),model); gl.uniformMatrix4fv(matrix,false,m); const selected=index===juniorViewport.selected; gl.uniform3fv(color,new Float32Array(selected?[0.82,0.48,0.25]:part.color)); gl.drawArrays(gl.TRIANGLES,0,36); }); };
const setStandardView = (view) => { if(view==='front'){juniorViewport.theta=0;juniorViewport.phi=1.1;} if(view==='top'){juniorViewport.theta=0;juniorViewport.phi=0.22;} if(view==='iso'){juniorViewport.theta=0.7;juniorViewport.phi=1.0;} renderWebgl(); };
if (viewportCanvas) { initWebgl(); viewportCanvas.addEventListener('pointerdown',(event)=>{ const button=event.button; if(button===0 && juniorViewport.mode==='measure'){ juniorViewport.measurePoints.push([event.offsetX,event.offsetY]); const badge=$('measure-badge'); badge.classList.remove('hidden'); if(juniorViewport.measurePoints.length===1){ badge.textContent='卷尺：选择第二个点'; } else { const a=juniorViewport.measurePoints.shift(), b=juniorViewport.measurePoints[0], pixels=Math.hypot(b[0]-a[0],b[1]-a[1]); badge.textContent=`卷尺：约 ${Math.round(pixels*1.4)} mm（原型估算）`; toast('已完成两点测量'); } return; } juniorViewport.drag={button,x:event.clientX,y:event.clientY}; viewportCanvas.setPointerCapture(event.pointerId); viewportCanvas.classList.add('dragging'); }); viewportCanvas.addEventListener('pointermove',(event)=>{ if(!juniorViewport.drag) return; const d=juniorViewport.drag, dx=event.clientX-d.x, dy=event.clientY-d.y; d.x=event.clientX;d.y=event.clientY; if(juniorViewport.mode==='move'){viewportParts[juniorViewport.selected].position[0]+=dx*0.003;viewportParts[juniorViewport.selected].position[1]-=dy*0.003;} else if(juniorViewport.mode==='rotate'){viewportParts[juniorViewport.selected].rotation+=dx*0.01;} else if(juniorViewport.mode==='scale'){const f=Math.max(0.4,Math.min(2,viewportParts[juniorViewport.selected].scale[0]-dy*0.005));viewportParts[juniorViewport.selected].scale=[f,f,f];} else if(d.button===1){juniorViewport.theta-=dx*0.01;juniorViewport.phi=Math.max(0.18,Math.min(2.8,juniorViewport.phi+dy*0.01));} else if(d.button===2){juniorViewport.panX-=dx*0.002;juniorViewport.panY+=dy*0.002;} renderWebgl(); }); viewportCanvas.addEventListener('pointerup',()=>{juniorViewport.drag=null;viewportCanvas.classList.remove('dragging');}); viewportCanvas.addEventListener('wheel',(event)=>{juniorViewport.distance=Math.max(0.55,Math.min(4,juniorViewport.distance+event.deltaY*0.001));renderWebgl();},{passive:true}); }
document.querySelectorAll('[data-view]').forEach((el)=>el.addEventListener('click',()=>setStandardView(el.dataset.view)));
document.querySelectorAll('[data-tool]').forEach((el)=>el.addEventListener('click',()=>{juniorViewport.mode=el.dataset.tool;if(el.dataset.tool==='mirror'){viewportParts[juniorViewport.selected].scale[0]*=-1;renderWebgl();}}));
render();
